higher-order.code:
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        String result = IntStream.rangeClosed(1, 10)
                .filter(n -> n % 2 == 0)
                .map(n -> n * n)
                .mapToObj(Integer::toString)
                .collect(Collectors.joining(" "));
        System.out.println(result);
    }
}

shapes.code:
public class Main {
    sealed interface Shape permits Rectangle, Triangle {
        int area();
    }

    record Rectangle(int width, int height) implements Shape {
        public int area() { return width * height; }
    }

    record Triangle(int base, int height) implements Shape {
        public int area() { return base * height / 2; }
    }

    public static void main(String[] args) {
        Shape[] shapes = { new Rectangle(3, 4), new Triangle(10, 3) };
        for (Shape s : shapes) {
            System.out.println(s.getClass().getSimpleName() + ": " + s.area());
        }
    }
}

